INSERT [catalogue].[Suppliers] ([Id], [Name], [LegalName], [Summary], [SupplierUrl], [Address], [Deleted], [LastUpdated], [LastUpdatedBy], [IsActive]) VALUES (10073, N'iPLATO', N'iPlato Healthcare Ltd', N'iPLATO has been operating mobile patient services in primary care since 2005. In this time we have launched the iPLATO service with over 1,800 GP practices in 75 CCG/PCTs reaching over 25 million patients.

iPLATO is the digital bridge between any of the principal GP IT systems used by the GP network and their patients using one of the most ubiquitous of modern tools – their own mobile phone.

•	Over 90% of adults in Britain own (at least one) mobile phone.
•	Personal, private and immediate – ideal for health communication.
•	Preferred by many patients, particularly the ‘hard-to-reach’.

More than 25 million patients in the UK already receive messages from their GP or Healthcare provider through iPLATO Patient Care Messaging for Primary Care system.', N'', N'{"line1":"1 King Street","town":"London","county":"Greater London","postcode":"W6 9HR","country":"England"}', 0, CAST(N'2020-04-01T13:48:54.1466667' AS DateTime2), 2, 1)
INSERT [catalogue].[Suppliers] ([Id], [Name], [LegalName], [Summary], [SupplierUrl], [Address], [Deleted], [LastUpdated], [LastUpdatedBy], [IsActive]) VALUES (99998, N'NotTPP', N'NotThe Phoenix Partnership', N'TPP is a digital health company, committed to delivering world-class healthcare software around the world. Its EHR product, SystmOne, is used by over 7,000 NHS organisations in over 25 different care settings. This includes significant deployments in Acute Hospitals, Emergency Departments, Mental Health services, Social Care services and General Practice. In recent years, TPP has increased its international presence, with live deployments in China and across the Middle East.', N'https://www.tpp-uk.com/', N'{"line1": "NotTPP Tower", "line2": "High Street", "city": "Leeds", "county": "West Yorkshire", "postcode": "LS1 1BB", "country": "UK"}', 0, CAST(N'2025-08-18T11:08:02.9000000' AS DateTime2), 2, 1)
INSERT [catalogue].[Suppliers] ([Id], [Name], [LegalName], [Summary], [SupplierUrl], [Address], [Deleted], [LastUpdated], [LastUpdatedBy], [IsActive]) VALUES (99999, N'NotEmis Health', N'NotEgton Medical Information Systems', N'We are the UK leader in connected healthcare software & services. Through innovative IT we help healthcare professionals access the information they need to provide better, faster and more cost effective patient care.

    Our clinical software is used in all major healthcare settings from GP surgeries to pharmacies, community, hospitals, and specialist services. By providing innovative, integrated solutions, we’re working to break the boundaries of system integration & interoperability.

    We also specialise in supplying IT infrastructure, software and engineering services, and through our technical support teams we have the skills and knowledge to enhance your IT systems.

    Patient (www.patient.info) is the UK’s leading health website. Designed to help patients play a key role in their own care, it provides access to clinically authored health information leaflets, videos, health check and assessment tools and patient forums.

    TRUNCATED FOR DEMO', N'www.emishealth.com', N'{"line1": "NotEmis Tower", "line2": "High Street", "city": "Leeds", "county": "West Yorkshire", "postcode": "LS1 1BB", "country": "UK"}', 0, CAST(N'2025-08-18T11:08:02.9000000' AS DateTime2), 2, 1)
