INSERT [catalogue].[Solutions] ([CatalogueItemId], [Category], [Summary], [FullDescription], [Features], [ClientApplication], [Hosting], [ImplementationDetail], [RoadMap], [IntegrationsUrl], [AboutUrl], [IsPilotSolution], [LastUpdated], [LastUpdatedBy]) VALUES (N'10072-006', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, CAST(N'2020-06-25T14:31:15.0166667' AS DateTime2), 2)
INSERT [catalogue].[Solutions] ([CatalogueItemId], [Category], [Summary], [FullDescription], [Features], [ClientApplication], [Hosting], [ImplementationDetail], [RoadMap], [IntegrationsUrl], [AboutUrl], [IsPilotSolution], [LastUpdated], [LastUpdatedBy]) VALUES (N'10073-009', NULL, N'Remote Consultation is a solution integrated into the iPLATO platform and myGP® app that helps GP practices avoid unnecessary appointments and supports remote consultation via chat, video and voice.

It allows practices to communicate with patients via video, audio and asynchronous messaging.', N'', N'["Proven to successfully reduce appointments demand by 20%.","Automated, clinically safe sign-posting to alternative pathways.","Offer local and national services to suitable patients.","Automated gathering of unstructured input from patient.","Read coding of patient information directly to IT system workflow.","CCG/STP service promotion e.g. smoking cessation, mental health.","myGP® app free for patients.","Fully GDPR compliant.","Manual appointment triage with advanced filtering and full-text search.","Consent requested during set up when enabling camera and audio."]', N'{"ClientApplicationTypes":["native-mobile"],"BrowsersSupported":[],"NativeMobileHardwareRequirements":"The user’s smartphone must be capable of making/receiving video calls.","NativeMobileFirstDesign":true,"MobileOperatingSystems":{"OperatingSystems":["Apple IOS","Android"],"OperatingSystemsDescription":"iPlato recommend users are always on the latest version of the OS"},"MobileConnectionDetails":{"MinimumConnectionSpeed":"1Mbps","ConnectionType":["4G","5G","Wifi"],"Description":"The minimum connection speed required to support a video call."},"MobileMemoryAndStorage":{"MinimumMemoryRequirement":"256MB","Description":"Application size is 33 Mb for iOS and 45 Mb for Android."},"MobileThirdParty":{"ThirdPartyComponents":"The application requires no additional 3rd party components or libraries.","DeviceCapabilities":"The user’s smartphone requires no special capabilities."}}', N'{"PrivateCloud":{"Summary":"All data used in the delivery of Remote Consultation is hosted at a UK based data centre by iPlato Healthcare. This data centre is secured and iPLATO is DSTP accredited.","Link":"","HostingModel":"","RequiresHSCN":"End user devices must be connected to HSCN/N3"}}', N'Remote consultation as a feature is available to all patients that have downloaded myGP v5.0 upwards so there is no implementation timescale as clinicians can opt to initiate a video call with the patient directly from the iPLATO system.', NULL, NULL, N'http://www.iplato.com/', 0, CAST(N'2020-04-01T12:49:33.9433333' AS DateTime2), 2)
INSERT [catalogue].[Solutions] ([CatalogueItemId], [Category], [Summary], [FullDescription], [Features], [ClientApplication], [Hosting], [ImplementationDetail], [RoadMap], [IntegrationsUrl], [AboutUrl], [IsPilotSolution], [LastUpdated], [LastUpdatedBy]) VALUES (N'99998-98', NULL, N'SystmOne GP has been evolving for over 20 years, with continuous clinical input. It is one of the most advanced clinical systems in the world and is used by more than 2,700 GP practices nationwide. SystmOne GP is the ideal solution to meet the ever-changing needs of modern General Practice.', N'SystmOne GP has been in use across UK General Practice for over 20 years. It is the system of choice for over 2,700 practices and is used by over 75,000 staff members. SystmOne GP is an advanced solution that goes far beyond the main functionality required for running a GP practice. It contains complete workflow support, a full analytics module, QOF tracking, and a comprehensive clinical development kit. Improving the quality of care across settings is core to TPP’s vision. The GP product is ideal for cross-organisational working and fully supports the requirements of Primary Care Networks.
            It enables true integrated care between GP, hospital, mental health and social care settings. TPP GP is Spine-accredited, providing access to the latest versions of GP2GP, EPS, and eRS. The system is fully compliant with SNOMED CT. SystmOne GP is leading on national interoperability programmes, compliant with national open FHIR standards for access to GP data and for transfer of care documentation.', N'["Full Spine Compliance – EPS, PDS, SCR, eRS, GP2GP","Standards – SNOMED CT, HL7 V2, V3, FHIR, GP Connect","Appointments – Configurable Clinics, Dedicated Appointments, Visits Screens, SMS Integration","Prescribing – Acute, Repeat, Formularies, Action Groups, Decision Support","Complete Electronic Health Record (EHR)","Comprehensive consultations – Recalls, Referrals, Structured Data","Clinical Development Kit – Data Entry Templates, Views, Questionnaires, Integrated Word Letters","Full Workflow Support including Automatic Consultations","Analytics – Customisable Reports, Batch Reports, Bulk Actions, QOF Tools, Automatic Submissions","Patient Online Services – Appointment Booking, Medication Requests, Record Access, Proxy Access"]', N'{"ClientApplicationTypes":["native-desktop"],"BrowsersSupported":[],"NativeMobileHardwareRequirements":"The OS system drive must have a drive letter of C.","NativeDesktopHardwareRequirements":"The OS system drive must have a drive letter of C.","NativeMobileFirstDesign":false,"MobileOperatingSystems":{"OperatingSystems":["Other"],"OperatingSystemsDescription":"Windows"},"MobileConnectionDetails":{"MinimumConnectionSpeed":"1Mbps","ConnectionType":["3G","4G","Wifi"],"Description":"CPU of 1 GHz or faster 32-bit or 64-bit processor"},"MobileMemoryAndStorage":{"MinimumMemoryRequirement":"1GB","Description":"4GB of free space on the C drive"},"MobileThirdParty":{"ThirdPartyComponents":"","DeviceCapabilities":"Minimum screen resolution of 1024 x 720 pixels."},"NativeDesktopOperatingSystemsDescription":"TPP supports all versions of Windows for desktops that are currently supported by Microsoft. Following verification of the configuration by TPP, installation of Windows to a virtual environment is supported to the products and versions including Virtual VMware View 5+, Citrix Xen Desktop 6+ and Microsoft Server 2012+.\r\nInstallation of the SystmOne client to any Server Operating System is not licensed by TPP. It should also be noted that both 32-bit and 64-bit versions of Microsoft Windows are supported unless otherwise stated. Windows RT is not supported.","NativeDesktopMinimumConnectionSpeed":"0.5Mbps","NativeDesktopThirdParty":{"ThirdPartyComponents":"Windows 7 requires 1GB and Office 2010 requires 256 MB. Other third party applications, shared graphics or peripherals (such as attached printers) should also be taken into account. These will all increase the amount of memory required for the computer to run smoothly.","DeviceCapabilities":"A minimum screen resolution of 1024 x 768 pixels with 16-bit colours is required. TPP recommends a minimum of a 17” TFT flat screen monitor with a resolution of 1280 x 1024 and 32-bit colours."},"NativeDesktopMemoryAndStorage":{"MinimumMemoryRequirement":"512MB","StorageRequirementsDescription":"4GB of free space on the C drive. Where a SystmOne Gateway client is used, 100GB of free space on the C drive is recommended.","MinimumCpu":"A minimum of a 2.0 GHz Pentium 4 series CPI is required.","RecommendedResolution":"5:4 – 1280 x 1024"},"NativeDesktopAdditionalInformation":"Applications that can open/view rich text file (.rtf) and comma separated (.csv) documents are required. To perform letter writing, Microsoft Word is also required. TPP only supportsversions of Office that are supported by Microsoft which currently includes Office 2010, 2013, 2016 and 2019."}', N'{"PrivateCloud":{"Summary":"The SystmOne Solution requires the following key items to be in place for smooth operation:\r\n-UDP Ports 2120-2130 and TCP Ports 2130-2140 should be opened to 20.146.120.128/25 and 20.146.248.128/25. TCP port 443 is also required for SystmOnline and Mobile Working to systmonline.tpp-uk.com. TPP also recommend allowing ICMP traffic for diagnostic purposes.\r\n\r\nA full list of requirements can be found in the SystmOne WES.","Link":"","HostingModel":"TPP provide a centralised solution with all server hardware hosted in TPP''s private cloud infrastructure. All server patching, security updates and feature releases are managed by TPP. The solution is hosted within 2 geographically separated private cloud instances with data replicated between the sites in real time in order to provide a high level of resiliency.\r\n\r\nTPP use a number of tools to monitor capacity, analyse usage trends and log the utilisation of the system. This ensures the solution scales to demand and new functionality / business requirements.","RequiresHSCN":"End user devices must be connected to HSCN/N3"}}', N'If a greenfield unit is required, the turn-around time to receive the Live unit can be as quick as two weeks, once a signed contract is in place and all staff have received the required training.
TPP will assess the request and set up the unit as specified in the order details. Once the Live system is ready to use, TPP will be in touch with the contact who requested the unit.

When transitioning from a previous system that has a mature adapter in place (EMIS Web, Vision, Microtest), implementation is a quick rollout of 8 weeks, including data migration of any existing patient records.

The main phases for this implementation are:
•	Initial data production
•	Data checking
•	Training
•	Data reload & sign-off
•	Final data production
•	Go Live

If transitioning from any other system, an additional 8-week adapter build period would be required.

TPP maintain close contact with staff at the unit throughout these phases to ensure an efficient and accurate implementation.', NULL, N'https://www.tpp-uk.com/partners', N'https://www.tpp-uk.com/products/systmone', 0, CAST(N'2025-08-18T11:08:03.1966667' AS DateTime2), 2)
INSERT [catalogue].[Solutions] ([CatalogueItemId], [Category], [Summary], [FullDescription], [Features], [ClientApplication], [Hosting], [ImplementationDetail], [RoadMap], [IntegrationsUrl], [AboutUrl], [IsPilotSolution], [LastUpdated], [LastUpdatedBy]) VALUES (N'99999-01', NULL, N'Summary - DFOCVC.', N'FULL DESCRIPTION – Digital First, Online Consultation and Video Consultation Solution.', N'["Digital Online Consultation","Video Consultation", "Fully interopable with all major GP IT solutions", "Compliant with all relevant ISO standards"]', N'{"ClientApplicationTypes":["browser-based"],"BrowsersSupported":[{"BrowserName":"Google Chrome","MinimumBrowserVersion":null},{"BrowserName":"Microsoft Edge","MinimumBrowserVersion":null}],"MobileResponsive":false,"Plugins":{"Required":false,"AdditionalInformation":null},"HardwareRequirements":"Webcam is required","NativeMobileHardwareRequirements":null,"NativeDesktopHardwareRequirements":null,"AdditionalInformation":null,"MinimumConnectionSpeed":null,"MinimumDesktopResolution":null,"MobileFirstDesign":null,"NativeMobileFirstDesign":null,"MobileOperatingSystems":null,"MobileConnectionDetails":null,"MobileMemoryAndStorage":null,"MobileThirdParty":null,"NativeMobileAdditionalInformation":null,"NativeDesktopOperatingSystemsDescription":null,"NativeDesktopMinimumConnectionSpeed":null,"NativeDesktopThirdParty":null,"NativeDesktopMemoryAndStorage":null,"NativeDesktopAdditionalInformation":null,"ExistingApplicationTypes":[0]}', N'{"PublicCloud":{"Summary":"Summary description","Link":"External URL link","RequiresHSCN":"Link to HSCN or N3 network required to access service"},"PrivateCloud":{"Summary":"Summary description","Link":"External URL link","HostingModel":"Hosting environment description","RequiresHSCN":"Link to HSCN or N3 network required to access service"},"HybridHostingType":{"Summary":"Summary description","Link":"External URL link","HostingModel":"Hosting environment description","RequiresHSCN":"Link to HSCN or N3 network required to access service"},"OnPremise":{"Summary":"Summary description","Link":"External URL link","HostingModel":"Hosting environment description","RequiresHSCN":"Link to HSCN or N3 network required to access service"}}', NULL, NULL, NULL, N'http://www.dfocvctest.com/about', 0, CAST(N'2025-08-18T12:23:37.9956768' AS DateTime2), 2)
INSERT [catalogue].[Solutions] ([CatalogueItemId], [Category], [Summary], [FullDescription], [Features], [ClientApplication], [Hosting], [ImplementationDetail], [RoadMap], [IntegrationsUrl], [AboutUrl], [IsPilotSolution], [LastUpdated], [LastUpdatedBy]) VALUES (N'99999-02', NULL, N'Summary - GPIT DFOCVC.', N'FULL DESCRIPTION – GPIT Futures, Digital First Online Consultation and Video Consultation Solution.', N'["Digital Online Consultation","Video Consultation", "Fully interopable with all major GP IT solutions", "Compliant with all relevant ISO standards"]', NULL, N'{"PublicCloud":{"Summary":"Summary description","Link":"External URL link","RequiresHSCN":"Link to HSCN or N3 network required to access service"},"PrivateCloud":{"Summary":"Summary description","Link":"External URL link","HostingModel":"Hosting environment description","RequiresHSCN":"Link to HSCN or N3 network required to access service"},"HybridHostingType":{"Summary":"Summary description","Link":"External URL link","HostingModel":"Hosting environment description","RequiresHSCN":"Link to HSCN or N3 network required to access service"},"OnPremise":{"Summary":"Summary description","Link":"External URL link","HostingModel":"Hosting environment description","RequiresHSCN":"Link to HSCN or N3 network required to access service"}}', NULL, NULL, NULL, N'http://www.gpitdfocvctest.com/about', 0, CAST(N'2025-08-18T11:08:03.1966667' AS DateTime2), 2)
INSERT [catalogue].[Solutions] ([CatalogueItemId], [Category], [Summary], [FullDescription], [Features], [ClientApplication], [Hosting], [ImplementationDetail], [RoadMap], [IntegrationsUrl], [AboutUrl], [IsPilotSolution], [LastUpdated], [LastUpdatedBy]) VALUES (N'99999-89', NULL, N'EMIS Web is the most widely used GP clinical system in the UK. Created by clinicians for clinicians, it helps run efficient practices, whilst delivering the best possible patient care. With patient safety at its core, EMIS Web enables you to deliver safe and informed on demand care across locations.', N'EMIS Web GP is a comprehensive, flexible and powerful clinical management tool for healthcare organisations. It is intuitive, easy to learn and was ranked the number one clinical system in the UK for interoperability (KLAS report).

EMIS Web GP is fully accredited to securely exchange data with the NHS SPINE and incorporates functionality such as GP2GP, Electronic Prescription Service (EPS), Personal Demographics Service (PDS), NHS e-Referral Service (e-RS) , Summary Care Record (SCR), eMED3 (Fitnotes), SNOMED CT and Female genital mutilation (FGM).

Using EMIS Web, healthcare professionals can provide the best possible patient care with patient safety at its core. We safely and securely hold more patient records than any other supplier and work with clinicians and pharmacists to ensure the highest possible standards of patient safety are upheld. The system provides secure access to all the information they need to make the right decisions for their patients.', N'["Access to real-time patient data that can be shared between locations and healthcare organisations","One-click access to patient summary information","Quick data entry using protocols, templates and concepts tailored to your practice requirements","Integrated clinical safety alerts graded to highlight severity","Automatic notification of linked pre-existing conditions when recording a new acute problem","Integrated patient recall system to target specific lists of patients for specific clinics","Intelligent alerts and auto-templates to capture outstanding QOF information","Integrated QOF-finder to identify patients where you are losing QOF points","Seamless data exchange with over 100 partners including Graphnet, Cerner and Optum","Integration with Patient Access enables patients to book appointments and order prescriptions"]', N'{"ClientApplicationTypes":["browser-based","native-mobile","native-desktop"],"BrowsersSupported":["Google Chrome","Chromium","Internet Explorer 11","Internet Explorer 10"],"MobileResponsive":true,"Plugins":{"Required":false,"AdditionalInformation":""},"MinimumConnectionSpeed":"2Mbps","MinimumDesktopResolution":"16:9 – 1366 x 768","HardwareRequirements":"The browser activities are only supported in relation the native desktop client therefore mirror the native desktop client hardware requirements detailed below.","NativeMobileHardwareRequirements":"Any device capable of supporting the listed supported operating systems is compliant.","NativeDesktopHardwareRequirements":"The spoke server is an important part of the solution. It provides a patch distribution system for client updates and acts as a local cache. \r\nEMIS Health recommends that your spoke is a dedicated device; however, if you use your spoke to perform other functions, such as act as a domain controller, store business documents or host other applications, then a Windows server class operating system will be required, along with an appropriate specification of server hardware.","AdditionalInformation":"","MobileFirstDesign":false,"NativeMobileFirstDesign":false,"MobileOperatingSystems":{"OperatingSystems":["Apple IOS","Android","Other"],"OperatingSystemsDescription":"•\tiOS v 10.3.3.3 and above\r\n•\tAndroid v 6 and above\r\n•\tWindows 10 (Build 14393)"},"MobileConnectionDetails":{"MinimumConnectionSpeed":"","ConnectionType":["GPRS","3G","LTE","4G","5G","Wifi"],"Description":"The mobile application only requires internet connectivity to synchronize therefore there is no minimum connection speed required."},"MobileMemoryAndStorage":{"MinimumMemoryRequirement":"2GB","Description":"All compliant devices have a minimum 16GB storage"},"MobileThirdParty":{"ThirdPartyComponents":"","DeviceCapabilities":"The device should have access to the relevant App Store to enable the installation of the respective application although deployment via mobile device management solutions is supported."},"NativeMobileAdditionalInformation":"Apple have recently announced that a new operating system, designed specifically for iPad devices.\r\nWe have tested this and can confirm that EMIS Mobile is fully compatible.","NativeDesktopOperatingSystemsDescription":"Microsoft Windows 7 (x86 x64)\r\nMicrosoft Windows 8.1 (x86 x64)\r\nMicrosoft Windows 10 (x86 x64)","NativeDesktopMinimumConnectionSpeed":"2Mbps","NativeDesktopThirdParty":{"ThirdPartyComponents":".NET framework 4","DeviceCapabilities":"The application requires connectivity to the EMIS Data Centre."},"NativeDesktopMemoryAndStorage":{"MinimumMemoryRequirement":"4GB","StorageRequirementsDescription":"10GB free disk space","MinimumCpu":"Intel Core i3 equivalent or higher","RecommendedResolution":"16:9 – 1366 x 768"},"NativeDesktopAdditionalInformation":"The minimum connection speed is dependent on the number of clients that need to be supported.\r\n\r\nEMISHealth do not support the use of on-screen keyboards for 2 in 1 devices."}', N'{"PublicCloud":{"Summary":"This service is not available on public cloud","Link":""},"PrivateCloud":{"Summary":"EMIS Web is hosted in EMIS’ own data centres and the solution is provided as Software as a Service","Link":"","HostingModel":"Model complies with GPIT Futures requirements for hosting","RequiresHSCN":"End user devices must be connected to HSCN/N3"}}', N'The typical timescales for the implementation of EMIS Web are around 12 weeks depending on the patient list size.

An implementation plan is provided and agreed at the beginning of the process outlining all key dates and activities, where required these dates are negotiable to fit the needs of the customer.

Key activities:

•	Customer supplied with high level implementation plan and welcome pack

•	Engineer visit to perform install of client software and check connectivity

•	Customer supplied test data loaded into a test system and made available

•	Learning needs analysis performed & agreed training plan for go live

•	On site visit to train the customer how to check and cleanse their data

•	Any defects and corrections completed on migrated data

•	Practice sign off of test data

•	Agreed training provide pre and post go live in line with results from LNA

•	Go live day, trainers and engineer onsite to support a smooth transition', N'The following roadmap details all IT Futures managed capacity items. EMIS Health is committed to delivering against the effective date. The roadmap provides visibility on which items have been completed, are scheduled and are in the pipeline to be scheduled.', N'https://www.emishealth.com/products/partner-products/', NULL, 0, CAST(N'2025-08-18T11:08:03.1966667' AS DateTime2), 2)

