INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'100000-001', N'Additional minutes for video consultations.', N'The typical number of units ordered is one. There is no maximum number that can be ordered.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10000-001', N'Initial configuration and set up of the system. This applies to the implementation phase.', N'Installations will be on an individual basis (one) to overarching organisations, such as Federations, CSGs or PCNs.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10000-002', N'EMIS Health can provide training services for Enterprise Search and Reports which are flexible and can be tailored to meet local requirements. These can be for live operations or used during the implementation phase. The maximum number of attendees is six.', N'A typical amount of training days for a new installation is likely to be six days. Additional training is available and would obviously be dependant on scale and user needs. Training is available on a needs basis. This could be one day or purchased in bulk.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10000-054', N'Customers can optionally separately purchase a qualified Egton Engineer’s time in half day increments to assist with moving or re-positioning Automated Arrivals equipment.', N'The typical number of units ordered is one. There should be no requirement to order more than one', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10000-062', N'Enterprise Search and Reports is the fast and efficient way to source, search and report on GP data in real time.', N'With the ability to develop custom searches, you can measure against your key objective, including QOF, LESs/DESs, referral activity and immunisations.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'100000-S-001', N'This service merges a single system into another. This service will be required by organisations who previously operated independently but are planning to merge their services, and so need to share a single instance of their software solution.\r\n\r\nPurchasing will allow two practices will combine the elements of both units (including patient lists, staff members, caseloads, etc.) into a single system.', N'Dependent on business need. This Associated Service (and corresponding fee) is for two practices merging into one, regardless of practice size. If more than two practices are merging, an additional Practice Merge will need to be purchased for each additional practice.', 1, CAST(N'2025-08-18T11:08:03.7533333' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'100000-S-002', N'This service ensure practice infrastructure is in place and has optimum configuration. This service is applicable to the implementation phase and live operations.', N'Dependent on the issue, a typical range is 1-7 days. Additional Engineering is available and would be dependant on scale and user needs. This could be one day or purchased in bulk.', 0, CAST(N'2025-08-18T11:08:03.7533333' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'100000-S-003', N'A fully managed, ISO compliant, service for the digitisation of Lloyd George records. We’ll collect your paper records, scan them and upload them into EMIS Web as digital files. Following sign-off paper records are securely destroyed by shredding them and then recycling them in an eco-friendly way.', N'The typical volume would be an average of eight thousand which is the typical practice capitation. The largest practice size is the maximum.', 0, CAST(N'2025-08-18T11:08:03.7533333' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'100000-S-004', N'We will take digitised Lloyd George files and upload them into EMIS Web. This allows for full visibility of a patients medical records from within the clinical system for more informed decisions at the point of care.', N'The typical volume would be an average of eight thousand which is the typical practice capitation. The largest practice size is the maximum.', 0, CAST(N'2025-08-18T11:08:03.7533333' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'100000-S-005', N'Our project management service can help organisations to seamlessly manage end-to-end projects based on their requirements. From initial planning to roll-out and ongoing project management, our team provides tailored support to customers.', N'Project Management resource is anticipated to be low for standard installations. For more complex deployments it is anticipated to be higher. The minimum is 1 day, maximum is 10 days per practice', 0, CAST(N'2025-08-18T11:08:03.7533333' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'100001-001', N'A solution to improve practice efficiency and patient experience.', N'Patients use a touchscreen to check-in and get an instruction on arrival and book available future appointments. Staff control the kiosk from a central portal for messages to patient groups and confirming personal data.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'100002-001', N'The integrated device is pre-loaded & configured with Anywhere Consult software, and also has Windows 10 operating system and Microsoft Office Professional installed.', N'The typical number of units ordered is one. There is no maximum number of units that can be ordered.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'100003-001', N'Five day course delivered onsite, providing in-depth training, allowing attendees to specialise in a wide range of SystmOne functionality. This service should be purchased by organisations wanting to enhance the training provided with the deployment of the Solution or Service. Super User Training ensures that users have the expertise to optimise the use of the Solution or Service across their organisation. Training can be tailored to suit a wide range of needs. Suitable for up to 8 attendees. A full day is 10am-4pm on site.', N'Dependent on business need. Purchase of training course is at the organisations discretion, it is not mandatory. There is no maximum number of courses purchased. Each course can accommodate up to 8 attendees; additional course(s) would need to be purchased if the number of attendees exceeds this.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'100004-001', N'The SystmOne GP Deployment - Full Training needs to be purchased for any practice migrating onto SystmOne without any training support from another organisation (e.g. their CCG).\r\n\r\nThis service includes:\r\n - Dedicated migration services to enable the secure transfer of data from a single Source Solution to SystmOne GP.\r\n- A comprehensive SystmOne GP End User Training course led by TPP Product Specialists, including pre and post GoLive support.\r\n- Training schedule: 5 Full Training Days to prepare for the deployment, 2 Full Training Days for technical and business Go-Live and 3 Full Training Days for post Go-Live support. This totals 10 Full Training Days.\r\nBy purchasing this service, a practice will ensure their data is successfully migrated from the incumbent system and all practice staff are fully trained on SystmOne.', N'Every practice migrating onto SystmOne will need to purchase either the SystmOne GP Deployment with Full Training or the SystmOne GP Deployment with Go Live Support. Maximum number required regardless of practice size is one.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'100005-001', N'The SystmOne GP Deployment - Go-Live Support will be purchased by any practice migrating onto SystmOne where they have training support from another organisation (e.g. from their CCG).\r\n\r\nThis includes:\r\n\- Dedicated migration services to enable the secure transfer of data from a single Source Solution to SystmOne GP.\r\n- Go-Live Support: 2 Full Training Days to cover Technical and Business Go-Live. Data migration with Go-Live support only is appropriate where CCGs have their own SystmOne-accredited training team to provide training to end users\r\nBy purchasing this service, a practice will ensure their data is migrated from the incumbent system with support from TPP during the Go Live.', N'Every practice migrating onto SystmOne will need to purchase either the SystmOne GP Deployment with Full Training or the SystmOne GP Deployment with Go Live Support. Maximum number required regardless of practice size is one', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10000-S-001', N'Additional minutes for video consultations.', N'The typical number of units ordered is one. There is no maximum number that can be ordered.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10000-S-002', N'Initial configuration and set up of the system. This applies to the implementation phase.', N'Installations will be on an individual basis (one) to overarching organisations, such as Federations, CSGs or PCNs.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10000-S-003', N'EMIS Health can provide training services for Enterprise Search and Reports which are flexible and can be tailored to meet local requirements. These can be for live operations or used during the implementation phase. The maximum number of attendees is six.', N'A typical amount of training days for a new installation is likely to be six days. Additional training is available and would obviously be dependant on scale and user needs. Training is available on a needs basis. This could be one day or purchased in bulk.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10000-S-004', N'Customers can optionally separately purchase a qualified Egton Engineer’s time in half day increments to assist with moving or re-positioning Automated Arrivals equipment.', N'The typical number of units ordered is one. There should be no requirement to order more than one', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10000-S-005', N'Enterprise Search and Reports is the fast and efficient way to source, search and report on GP data in real time.', N'With the ability to develop custom searches, you can measure against your key objective, including QOF, LESs/DESs, referral activity and immunisations.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10000-S-006', N'A solution to improve practice efficiency and patient experience.', N'Patients use a touchscreen to check-in and get an instruction on arrival and book available future appointments. Staff control the kiosk from a central portal for messages to patient groups and confirming personal data.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10000-S-007', N'Customers can optionally separately purchase a qualified Egton Engineer’s time in half day increments to assist with moving or re-positioning Automated Arrivals equipment.', N'The typical number of units ordered is one. There should be no requirement to order more than one', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10000-S-008', N'Egton can provide additional specialist services for network cabling from the Automated Arrivals endpoint up to the patch panel outside the server equipment room.', N'The typical number of units ordered is one. There should be no requirement to order more than one', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10000-S-009', N'The integrated device is pre-loaded & configured with Anywhere Consult software, and also has Windows 10 operating system and Microsoft Office Professional installed.', N'The typical number of units ordered is one. There is no maximum number of units that can be ordered.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10000-S-036', N'This service ensure practice infrastructure is in place and has optimum configuration. This service is applicable to the implementation phase and live operations.', N'Dependent on the issue, a typical range is 1-7 days. Additional Engineering is available and would be dependant on scale and user needs. This could be one day or purchased in bulk.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10000-S-037', N'A fully managed, ISO compliant, service for the digitisation of Lloyd George records. We’ll collect your paper records, scan them and upload them into EMIS Web as digital files. Following sign-off paper records are securely destroyed by shredding them and then recycling them in an eco-friendly way.', N'The typical volume would be an average of eight thousand which is the typical practice capitation. The largest practice size is the maximum.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10000-S-038', N'We will take digitised Lloyd George files and upload them into EMIS Web. This allows for full visibility of a patients medical records from within the clinical system for more informed decisions at the point of care.', N'The typical volume would be an average of eight thousand which is the typical practice capitation. The largest practice size is the maximum.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10000-S-039', N'This service ensures that data is transferred as comprehensively, accurately and as quickly as possible, preserving its context and meaning. EMIS Health understands the importance of minimising the disruption during the data migration. This service applies to the implementation phase.', N'The typical unit of order is expected to be on an individual practice migration basis (one). Migrations could potentially be ordered for a whole CCG if there was a bulk request (up to one hundred).', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10000-S-040', N'Our practice reorganisation service provides support during practice splits and mergers. When two or more practices decide to split or merge clinical information, our service can target either select patients or the full patient list. It makes organising a change in practice simple. This service is applicable to both implementation and live operations.', N'The typical unit of order for practice mergers and splits is likely to be on an individual basis (one). This is a fixed fee per practice regardless of size.', 3, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10000-S-041', N'Our project management service can help organisations to seamlessly manage end-to-end projects based on their requirements. From initial planning to roll-out and ongoing project management, our team provides tailored support to customers.', N'Project Management resource is anticipated to be low for standard installations. For more complex deployments it is anticipated to be higher. The minimum is 1 day, maximum is 10 days per practice.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10000-S-042', N'Our service provides support during practice mergers. When two or more practices decide to split or merge clinical information, our service can target either select patients or the full patient list. It makes organising a change in practice simple. This service is applicable to both implementation and live operations.', N'The typical unit of order for practice mergers and splits is likely to be on an individual basis (one). This is a fixed fee per practice regardless of size.', 1, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10000-S-043', N'Our service provides support during practice splits . When two or more practices decide to split or merge clinical information, our service can target either select patients or the full patient list. It makes organising a change in practice simple. This service is applicable to both implementation and live operations.', N'The typical unit of order for practice mergers and splits is likely to be on an individual basis (one). This is a fixed fee per practice regardless of size.', 2, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
