INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10004-S-001', N'EMIS Health can provide a wide range of training services which are flexible and can be tailored to meet local requirements or goals. Our experienced training team will support you in using your clinical system to its full potential and ensure patient data is captured correctly and effectively. This service is applicable to both the implementation phase and live operations', N'A typical amount of training days for a new installation is likely to be six days. Additional training is available and would obviously be dependant on scale and user needs. Training is available on a needs basis. This could be one day or purchased in bulk.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10004-S-002', N'Customisation importance of minimising the disruption during the data migration. This service applies to the implementation phase.', N'The typical unit of order is expected to be on an individual practice migration basis (one). Migrations could potentially be ordered for a whole CCG if there was a bulk request (up to one hundred).', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10004-S-003', N'A group training session for CCG & practice staff on the use of the solution. There is no specific limit on how many staff or practices can attend the training, but 20-30 is a typical number. The commissioning organisation usually makes the venue available at their own cost.', N'A commissioning organisation will usually require a single training seminar to cover all participating practices. Multiple seminar days can be booked to work with fewer numbers of participants, or to assist with geographical outreach.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10004-S-004', N'Supports the secure migration of Practice data between Solutions.', N'Migrations could potentially be ordered for a whole CCG if there was a bulk request (up to one hundred).', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10007-S-001', N'Provides for adding and customising of any local content (e.g. ref forms & pathways) that exceed the 100 free document included in annual license fee. Ensures currency of local content & consistency of treatment guidelines.', N'The typical unit of order ranges from 50 to 100 document. There is no minimum and maximum unit of order.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10007-S-002', N'For practices that currently have the solution database installed locally at their practice, enables these databases to be moved to a centrally hosted server on the NHS secure network or; Provides for the migration of the solution from the existing clinical system to a new one.', N'To migrate the system from a practice hosted database to a centrally hosted database or migrate from the existing clinical system to a new system will typically require one day per practice. There is no maximum number.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10007-S-003', N'Provides for the remote installation of the solution at each of the required practices and workstations plus registering of users enabling role based access and user preferences. Following this the system is live for on-site training and operational use.', N'The typical number of units ordered equals the number of practices to which the solution needs to be deployed. As an example, an order for 40 practices will equal 40 units. There are no maximum units of order.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10007-S-004', N'Provides for the enhancement of user workflow between tools in the clinical system (e.g. templates) and content within DXS Best Pathway or any other discrete project based requirements. e.g. linking local templates to appropriate content for easy access', N'There is no typical unit of order as requirements are defined by the client. There is no maximum unit of order.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10007-S-005', N'To ensure max use of the solution provides for on-site training of practice staff after deployment at each practice. Supported by comprehensive printed & online training material. Additional training can be purchase under Associate Services.', N'Typical unit of order equals one full days face to face training at a chosen venue for all practice staff requiring training. There are no maximum units of order.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10029-S-006', N'Our project management service can help organisations to seamlessly manage end-to-end projects based on their requirements. From initial planning to roll-out and ongoing project management, our team provides tailored support to customers.', N'Project Management resource is anticipated to be low for standard installations. For more complex deployments it is anticipated to be higher. The minimum is 1 day, maximum is 10 days per practice.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10029-S-007', N'Business Analysis is a research discipline of identifying business needs and determining solutions to business problems.', N'Solutions often include a software-systems development component, but may also consist of process improvements, organizational change or strategic planning and policy development.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
