INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10029-S-009', N'Information Architecture is the structural design of shared information environments', N'Typically, it involves a model or concept of information that is used and applied to activities which require explicit details of complex information systems.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10029-S-010', N'Staff training is a programme implemented by a manager or person of authority to provide specific staff members with the necessary skills and knowledge for their current role.', N'It is often compulsory for some level of training to be offered to new members of staff as you prepare them for their role.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
