INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10046-S-002', N'If a practice merges with another or if the practice is splitting in to two or more, this service will deliver the required Docman technical work, working with your clinical system supplier. Only 1 day is required for a merger or practice split, each practice does not have to purchase separate days', N'New Customers:\r\nTypical Quantity - 1 day\r\nExisting Customers:\r\nTypical Quantity - 1 day', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
