INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10046-S-004', N'Two days on-site training for Docman10X for new customers.\r\nAdditional on-site training can be purchased for example,\r\ntraining new staff, health checks or a day designed by the customer to meet the Practice needs. If purchasing more than one day of training, then the days must be used consecutively', N'New Customers:\r\nTypical Quantity - 1 day\r\nExisting Customers:\r\nTypical Quantity - 2 days', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10046-S-005', N'Pre-deployment, deployment, sustainment, re-deployment and post-deployment.', N'Each stage is characterized both by a time frame and specific emotional challenges, which must be dealt with and mastered by each of the Family members.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10046-S-006', N'Post-deployment, deployment, sustainment, re-deployment and post-deployment.', N'Each stage is characterized both by a time frame and specific emotional challenges, which must be dealt with and mastered by each of the Family members.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10046-S-007', N'A remote day that is purchased to migrate the Docman 7 data into the new Docman10X environment', N'New Customers:\r\n Typical Quantity - 1 day\r\nExisting Customers:\r\nTypical Quantity - 1 day', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
