INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10046-S-009', N'Docman 10 is a scanning and document management system, which integrates with Vision to enable documents to be scanned and filed into the patient record.', N'Docman 10 is a scanning and document management system, which integrates with Vision to enable documents to be scanned and filed into the patient record.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10046-S-010', N'A remote day for new Docman customer to enable the database creation and technical activities to generate the new Docman10X system', N'New Customers:\r\nTypical Quantity - 1 day\r\nExisting Customers:\r\nTypical Quantity - 1 day', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10047-S-001', N'Pathfinder can provide additional specialist services for network cabling.', N'The typical number of units ordered is one. There should be no requirement to order more than one.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10047-S-002', N'Transform service can target either select patients or the full patient list.', N'The typical unit of order for practice mergers and splits is likely to be on an individual basis (one).', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10052-S-001', N'One day of training by a TPP Product Specialist. Training can be tailored to suit a wide range of needs. For example, training could be focussed on a specific area of system functionality or a particular workflow. A full day is 10am-4pm. The Product Specialist will attend on site.', N'Purchase of training days is at the buyers discretion and dependent on business need. The number of days required will vary depending on what training is required.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10052-S-002', N'One half-day of training by a TPP Product Specialist. Training can be tailored to suit a wide range of needs. For example, training could be focussed on a specific area of system functionality or a particular workflow. A half-day is 10am-1pm or 1pm-4pm. The Product Specialist will attend on site', N'Purchase of training days is at the buyers discretion and dependent on business need. The number of days required will vary depending on what training is required - for example, whether this is to train new staff on the system or just to enhance users knowledge of functionality. There are no minimum or maximum units of order', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10052-S-003', N'Five day course delivered onsite, providing in-depth training, allowing attendees to specialise in a wide range of SystmOne functionality. This service should be purchased by organisations wanting to enhance the training provided with the deployment of the Solution or Service. Super User Training ensures that users have the expertise to optimise the use of the Solution or Service across their organisation. Training can be tailored to suit a wide range of needs. Suitable for up to 8 attendees. A full day is 10am-4pm on site.', N'Dependent on business need. Purchase of training course is at the organisations discretion, it is not mandatory. There is no maximum number of courses purchased. Each course can accommodate up to 8 attendees; additional course(s) would need to be purchased if the number of attendees exceeds this.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10052-S-004', N'Web based Train the Trainer course, associated materials, on line, content and document resources and support for Call off Ordering Party trainers, so they can implement the service as intended correctly and safely.', N'Usually x1 course per call off where a call off = 1 CCG Larger scale call offs typically x1 course per 3 CCGs', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10052-S-005', N'This Associated Service is purchased by buyers for training and testing purposes. The training environment is a near-replica of the live SystmOne environment and is updated in line with updates to the live system. It can be accessed by multiple users simultaneously. Configuration of the environment and the creation of test data to be done by the Call Off Ordering Party. Additional Services can be enabled, on request, at the Training Environment purchased for the applicable Solution, with the exception of Mobile Working which requires a different (separate) training environment.', N'Dependent on business need and contracting organisations approach to training. For example, a CCG with a central training team may purchase one training unit for demonstrating functionality to different practices, or each GP practice may wish to have their own training environment.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10052-S-008', N'The SystmOne GP Deployment - Go-Live Support will be purchased by any practice migrating onto SystmOne where they have training support from another organisation (e.g. from their CCG).\r\n\r\nThis includes:\r\n\- Dedicated migration services to enable the secure transfer of data from a single Source Solution to SystmOne GP.\r\n- Go-Live Support: 2 Full Training Days to cover Technical and Business Go-Live. Data migration with Go-Live support only is appropriate where CCGs have their own SystmOne-accredited training team to provide training to end users\r\nBy purchasing this service, a practice will ensure their data is migrated from the incumbent system with support from TPP during the Go Live.', N'Every practice migrating onto SystmOne will need to purchase either the SystmOne GP Deployment with Full Training or the SystmOne GP Deployment with Go Live Support. Maximum number required regardless of practice size is one', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10052-S-009', N'This service merges a single SystmOne GP unit into another. This service will be required by organisations who previously operated independently but are planning to merge their services, and so need to share a single instance of their software solution.\r\n\r\nPurchasing will allow two practices will combine the elements of both units (including patient lists, staff members, caseloads, etc.) into a single SystmOne unit.', N'Dependent on business need. This Associated Service (and corresponding fee) is for two practices merging into one, regardless of practice size. If more than two practices are merging, an additional Practice Merge will need to be purchased for each additional practice.', 1, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10052-S-010', N'This service splits a single SystmOne GP unit into two units. This service will be required by organisations who previously operated as one practice and are splitting into separate organisations.\r\n\r\nA Practice Split will allow an organisation currently working as a single entity to separate business elements between two individual SystmOne units. Patient records will be split between the two units.', N'Dependent on business need. This Associated Service (and corresponding fee) is for one GP practice splitting into two, regardless of practice size. If the practice is splitting into more than two new entities, an additional Practice Split will need to be purchased for each additional new practice.', 2, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10052-S-011', N'This service can be purchased where an organisation wants to transfer deducted patient data and/or audit data to a secured portable USB device at the point of a migration to SystmOne GP. This service is to ensure, where necessary, the provision of deducted patient records taken from the incoming practice legacy system, which are not migrated onto SystmOne GP.\r\nThese records are not migrated as the patients are no longer receiving care at that practice. The USB can also be requested for audit purposes. Practices will be provided with a USB holding the data.', N'Dependent on business need. Maximum purchase required is typically one USB per practice. The practice size does not affect the number of USBs required.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10052-S-012', N'Data extraction services help tap the vast data resources available online or within internal sources and extract the data so that it can be used to benefit the business.', N'This post is a data extraction services guide to help you with your data management.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10052-S-013', N'The SystmOne GP Deployment - Full Training needs to be purchased for any practice migrating onto SystmOne without any training support from another organisation (e.g. their CCG).\r\n\r\nThis service includes:\r\n - Dedicated migration services to enable the secure transfer of data from a single Source Solution to SystmOne GP.\r\n- A comprehensive SystmOne GP End User Training course led by TPP Product Specialists, including pre and post GoLive support.\r\n- Training schedule: 5 Full Training Days to prepare for the deployment, 2 Full Training Days for technical and business Go-Live and 3 Full Training Days for post Go-Live support. This totals 10 Full Training Days.\r\nBy purchasing this service, a practice will ensure their data is successfully migrated from the incumbent system and all practice staff are fully trained on SystmOne.', N'Every practice migrating onto SystmOne will need to purchase either the SystmOne GP Deployment with Full Training or the SystmOne GP Deployment with Go Live Support. Maximum number required regardless of practice size is one.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10063-S-004', N'Implementation services rely on a structured, comprehensive approach from design to testing to help you achieve optimal outcomes from your software solution quickly.', N'It takes the right mix of industry and technology expertise to realize successful software deployments that help you advance your business.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10063-S-005', N'Implementation service needed to enable deployment of Core software components and integration services to GP Practices by Call Off Ordering Party or their agent e.g. CSU GP IT\r\nsupport service. This provides software components to integrate with source clinical system and enable access and operation of the solution.', N'Service usually purchased at CCG or STP scale which means practice numbers can be from 15 to more than 200', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10063-S-006', N'Support services provide internal support to the main business of organization.', N'Activities provided to or on behalf of a person in the areas of personal care and assistance and property maintenance in order to allow a person to live in the least restrictive environment.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10063-S-007', N'Defines the training activities and collateral expected from Suppliers to support the buyers and users of their Solutions.', N'A typical amount of training for a new installation is likely to be one day. Additional training is available and would obviously be dependant on scale and user needs. Training is available on a needs basis. This could be one day or purchased in bulk.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10063-S-008', N'EMIS Health can provide a wide range of training services which are flexible and can be tailored to meet local requirements or goals. These can be for live operations or used during the implementation phase. The maximum number of attendees is six.', N'The typical number of units ordered is one. There is no maximum number of units that can be ordered.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10063-S-009', N'A group training session for CCG & practice staff on the use of the solution. There is no specific limit on how many staff or practices can attend the training, but 20-30 is a typical number. The commissioning organisation usually makes the venue available at their own cost.', N'A commissioning organisation will usually require a single training seminar to cover all participating practices. Multiple seminar days can be booked to work with fewer numbers of participants, or to assist with geographical outreach.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10063-S-010', N'Form and Document Creation is one of the things that technical communicators do as part of creating deliverables for their companies or clients.', N'Document design is: "the field of theory and practice aimed at creating comprehensible, persuasive and usable functional documents', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10072-S-005', N'Push Access - Implementation DESCRIPTION', N'', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10072-S-010', N'Initial configuration and set up of the system. This service is applicable to the Implementation phase.', N'Installations will be on an individual basis (one) to practices although CCGs might purchase this in bulk for multiple practices.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10072-S-011', N'Initial configuration and set up of the system. This service is applicable to the Implementation phase.', N'Installations will be on an individual basis (one) to practices although CCGs might purchase this in bulk for multiple practices.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10072-S-012', N'This can be used at any time to provide refresher training for new teams ', N'You can order this at any time during the life of the service. This can be split across multiple practices within a PCN, Federation or ICS up to 12 attendees ', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10072-S-013', N'We will provide a banner for your surgery, leaflets for patient information and can provide digital assets for your website to enable you to advertise your new digital service to your patients', N'Surgeries can order at multiple times during the life of the service, although we generally recommend that this is used when the service is first activated', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10073-S-021', N'Setup/Provisioning/Launch seamlessly manage end-to-end projects based on their requirements.', N'Project Management resource is anticipated to be low for standard installations. For more complex deployments it is anticipated to be higher.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10073-S-022', N'If required group or individual User Training programmes can be undertaken and will be charged based on standard session rates.', N'Typical units of order 1 (existing customer). Typical units of order 2 (new customer). No maximum order size.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)
INSERT [catalogue].[AssociatedServices] ([CatalogueItemId], [Description], [OrderGuidance], [PracticeReorganisationType], [LastUpdated], [LastUpdatedBy]) VALUES (N'10073-S-023', N'My GP Integration is anticipated to be low for standard installations. For more complex deployments', N'resource is anticipated to be low for standard installations. For more complex deployments it is anticipated to be higher.', 0, CAST(N'2025-08-18T11:08:04.2100000' AS DateTime2), 2)

INSERT [catalogue].[AdditionalServices] ([CatalogueItemId], [Summary], [FullDescription], [LastUpdated], [LastUpdatedBy], [SolutionId]) VALUES (N'100000-001-A01', N'Addition to Write on Time', N'Write on time Addttion Full Description', CAST(N'2025-08-18T11:08:03.5700000' AS DateTime2), 2, N'100000-001')
INSERT [catalogue].[AdditionalServices] ([CatalogueItemId], [Summary], [FullDescription], [LastUpdated], [LastUpdatedBy], [SolutionId]) VALUES (N'10000-001A001', N'Long Term Conditions Manager', N'Long Term Conditions (LTC) Manager provides easy-to-use, intelligent templates and alerts in EMIS Web, so you can provide fast, efficient and safe LTC management. Stratify patients by complexity and distribute work among clinicians and healthcare assistants with varying skill mix.', CAST(N'2025-08-18T11:08:04.1466667' AS DateTime2), 2, N'10000-001')
INSERT [catalogue].[AdditionalServices] ([CatalogueItemId], [Summary], [FullDescription], [LastUpdated], [LastUpdatedBy], [SolutionId]) VALUES (N'10000-001A002', N'EMIS Mobile', N'EMIS Mobile supports offline, out-of-practice working for healthcare professionals, providing access to a patient’s care record, updating consultations/encounters with data, booking appointments, tasks and medication. Native apps for iOS, Android and Windows 10 ensure an optimised user experience.', CAST(N'2025-08-18T11:08:04.1466667' AS DateTime2), 2, N'10000-001')
INSERT [catalogue].[AdditionalServices] ([CatalogueItemId], [Summary], [FullDescription], [LastUpdated], [LastUpdatedBy], [SolutionId]) VALUES (N'10000-001A003', N'Automated Arrivals', N'A solution to improve practice efficiency and patient experience. Patients use a touchscreen to check-in and get an instruction on arrival and book available future appointments. Staff control the kiosk from a central portal for messages to patient groups and confirming personal data.', CAST(N'2025-08-18T11:08:04.1466667' AS DateTime2), 2, N'10000-001')
INSERT [catalogue].[AdditionalServices] ([CatalogueItemId], [Summary], [FullDescription], [LastUpdated], [LastUpdatedBy], [SolutionId]) VALUES (N'10000-001A004', N'Extract Services', N'Mobilising data within EMIS systems to assist commissioners and providers of care with clinical decision making.', CAST(N'2025-08-18T11:08:04.1466667' AS DateTime2), 2, N'10000-001')
INSERT [catalogue].[AdditionalServices] ([CatalogueItemId], [Summary], [FullDescription], [LastUpdated], [LastUpdatedBy], [SolutionId]) VALUES (N'10000-001A005', N'EMIS Web Dispensing', N'EMIS Web provides integrated functionality to support dispensing doctors who provide primary healthcare to UK rural patients. This enables dispensing GP practices to provide access to medicines and general healthcare under one roof.', CAST(N'2025-08-18T11:08:04.1466667' AS DateTime2), 2, N'10000-001')
INSERT [catalogue].[AdditionalServices] ([CatalogueItemId], [Summary], [FullDescription], [LastUpdated], [LastUpdatedBy], [SolutionId]) VALUES (N'10000-001A006', N'Document Management', N'EMIS Web Document Management helps you workflow both scanned and electronically received documents in your practice, such as Out of Hours notifications, Hospital Discharge letters and NHS111 notifications. Assign different kinds of tasks to different users or teams, so you can work more efficiently.', CAST(N'2025-08-18T11:08:04.1466667' AS DateTime2), 2, N'10000-001')
INSERT [catalogue].[AdditionalServices] ([CatalogueItemId], [Summary], [FullDescription], [LastUpdated], [LastUpdatedBy], [SolutionId]) VALUES (N'10000-001A007', N'Risk Stratification', N'Risk Stratification tools are specifically designed to identify those individuals who are at high risk of experiencing a future adverse event, such as readmission to hospital or unplanned hospital admission, or an acute event such as a heart attack. Risk Stratification often takes into account multiple risk factors and morbidities and their inter dependency, rather than just concentrating on one criterion (e.g. high blood pressure).\nA Risk Stratification Capability will allow risk calculations to be performed for individual patients using algorithms that can be run against Patient data (known algorithms can be used such as QRISK®2, QDiabetes®, QFracture®, QCancer®, QAdmissions®) to proactively identify a Patient risk level ', CAST(N'2025-08-18T11:08:04.1466667' AS DateTime2), 2, N'10000-001')
INSERT [catalogue].[AdditionalServices] ([CatalogueItemId], [Summary], [FullDescription], [LastUpdated], [LastUpdatedBy], [SolutionId]) VALUES (N'10000-001A008', N'Enterprise Search and Reports', N'Enterprise Search and Reports is the fast and efficient way to source, search and report on GP data in real time. With the ability to develop custom searches, you can measure against your key objective, including QOF, LESs/DESs, referral activity and immunisations.', CAST(N'2025-08-18T11:08:04.1466667' AS DateTime2), 2, N'10000-001')
INSERT [catalogue].[AdditionalServices] ([CatalogueItemId], [Summary], [FullDescription], [LastUpdated], [LastUpdatedBy], [SolutionId]) VALUES (N'100001-001-A01', N'Addition to Appointment Gateway', N'Appointment Gateway Addition Full Description', CAST(N'2025-08-18T11:08:03.5700000' AS DateTime2), 2, N'100001-001')
INSERT [catalogue].[AdditionalServices] ([CatalogueItemId], [Summary], [FullDescription], [LastUpdated], [LastUpdatedBy], [SolutionId]) VALUES (N'100002-001-A01', N'Addition to Zen Guidance', N'Zen Guidance Addition Full Description', CAST(N'2025-08-18T11:08:03.5700000' AS DateTime2), 2, N'100002-001')
INSERT [catalogue].[AdditionalServices] ([CatalogueItemId], [Summary], [FullDescription], [LastUpdated], [LastUpdatedBy], [SolutionId]) VALUES (N'100004-001-A01', N'Addition to Diagnostics XYZ', N'Diagnostics XYZ Addition Full Description', CAST(N'2025-08-18T11:08:03.5700000' AS DateTime2), 2, N'100004-001')
INSERT [catalogue].[AdditionalServices] ([CatalogueItemId], [Summary], [FullDescription], [LastUpdated], [LastUpdatedBy], [SolutionId]) VALUES (N'100005-001-A01', N'Addition to Document Wizard', N'Document Wizard Addition Full Description', CAST(N'2025-08-18T11:08:03.5700000' AS DateTime2), 2, N'100005-001')
INSERT [catalogue].[AdditionalServices] ([CatalogueItemId], [Summary], [FullDescription], [LastUpdated], [LastUpdatedBy], [SolutionId]) VALUES (N'100006-001-A01', N'Addition to Paperlite', N'Paperlite Addition Full Description', CAST(N'2025-08-18T11:08:03.5700000' AS DateTime2), 2, N'100006-001')
INSERT [catalogue].[AdditionalServices] ([CatalogueItemId], [Summary], [FullDescription], [LastUpdated], [LastUpdatedBy], [SolutionId]) VALUES (N'100007-001-A01', N'Addition to Medsort', N'Medsort Addition Full Description', CAST(N'2025-08-18T11:08:03.5700000' AS DateTime2), 2, N'100007-001')
INSERT [catalogue].[AdditionalServices] ([CatalogueItemId], [Summary], [FullDescription], [LastUpdated], [LastUpdatedBy], [SolutionId]) VALUES (N'100007-002-A01', N'Addition to Boston Dynamics', N'Boston Dynamics Addition Full Description', CAST(N'2025-08-18T11:08:03.5700000' AS DateTime2), 2, N'100007-002')
INSERT [catalogue].[AdditionalServices] ([CatalogueItemId], [Summary], [FullDescription], [LastUpdated], [LastUpdatedBy], [SolutionId]) VALUES (N'10007-002A001', N'Localised Referral Forms', N'Build and maintain a maximum of 100 custom items according to local guidelines for a PCN, GP Federation , CCG or STP as supplied by the client. Saving users time by reducing the burden of customising documentation according to local requirements to drive uniformity in care', CAST(N'2025-08-18T11:08:04.1466667' AS DateTime2), 2, N'10007-002')
INSERT [catalogue].[AdditionalServices] ([CatalogueItemId], [Summary], [FullDescription], [LastUpdated], [LastUpdatedBy], [SolutionId]) VALUES (N'10007-002A002', N'Localised Supporting Content', N'Build and maintain a maximum of 100 custom items according to local guidelines for a PCN, GP Federation, CCG or STP as supplied by the client. Saving users time by reducing the burden of customising documentation according to local requirements to drive uniformity in care', CAST(N'2025-08-18T11:08:04.1466667' AS DateTime2), 2, N'10007-002')
INSERT [catalogue].[AdditionalServices] ([CatalogueItemId], [Summary], [FullDescription], [LastUpdated], [LastUpdatedBy], [SolutionId]) VALUES (N'10030-001A001', N'AccuRx Video Consultation', N'The Video Consultation Capability allows Health or Care Professionals to conduct secure live remote video consultations with individual or groups of Patients/Service Users/Proxies ensuring they can receive support relating to healthcare concerns when a Video Consultation is most appropriate', CAST(N'2025-08-18T11:08:04.1466667' AS DateTime2), 2, N'10030-001')
INSERT [catalogue].[AdditionalServices] ([CatalogueItemId], [Summary], [FullDescription], [LastUpdated], [LastUpdatedBy], [SolutionId]) VALUES (N'10035-001A001', N'Digital First Consultations', N'Digital First Consultations enables remote working for clinicians, including video-based appointments, with or without access to the regular practice IT system. Patients can book a digital consultation, share their record with the clinician and notes are sent back to the GP system via interfaces.', CAST(N'2025-08-18T11:08:04.1466667' AS DateTime2), 2, N'10035-001')
INSERT [catalogue].[AdditionalServices] ([CatalogueItemId], [Summary], [FullDescription], [LastUpdated], [LastUpdatedBy], [SolutionId]) VALUES (N'10052-002A001', N'SystmOne Enhanced', N'SystmOne Enhanced is a comprehensive package of advanced features that improve the efficiency and workflow of practices. The tools offer additional administrative and clinical support to promote higher standards of care and improve data quality. The following areas of functionality are included: Document Management and Scanning: Document processing is quick and easy, reducing administrative burden and saving valuable time.', CAST(N'2025-08-18T11:08:04.1466667' AS DateTime2), 2, N'10052-002')
INSERT [catalogue].[AdditionalServices] ([CatalogueItemId], [Summary], [FullDescription], [LastUpdated], [LastUpdatedBy], [SolutionId]) VALUES (N'10052-002A002', N'SystmOne Mobile Working', N'Users can access their SystmOne unit and its data via a mobile client available on devices such as tablets. This can be used both online and offline, e.g. in the community where an internet connection may not always be available.', CAST(N'2025-08-18T11:08:04.1466667' AS DateTime2), 2, N'10052-002')
INSERT [catalogue].[AdditionalServices] ([CatalogueItemId], [Summary], [FullDescription], [LastUpdated], [LastUpdatedBy], [SolutionId]) VALUES (N'10052-002A003', N'SystmOne Auto Planner', N'SystmOne AutoPlanner ensures staff with the necessary skillsets are routed to the right patient homes in the most efficient way.', CAST(N'2025-08-18T11:08:04.1466667' AS DateTime2), 2, N'10052-002')
INSERT [catalogue].[AdditionalServices] ([CatalogueItemId], [Summary], [FullDescription], [LastUpdated], [LastUpdatedBy], [SolutionId]) VALUES (N'10052-002A004', N'SystemOne Shared Admin', N'Organisations can choose to share administrative duties with other organisations to more efficiently manage workloads and reduce staff burden.', CAST(N'2025-08-18T11:08:04.1466667' AS DateTime2), 2, N'10052-002')
INSERT [catalogue].[AdditionalServices] ([CatalogueItemId], [Summary], [FullDescription], [LastUpdated], [LastUpdatedBy], [SolutionId]) VALUES (N'10052-002A005', N'TPP Video Conferencing with Airmid', N'TPP video consultation functionality provides remote access to patients for the purpose of providing direct healthcare. Video consultations mean that face to face appointments can occur electronically without the need for either party to travel to a specified location.', CAST(N'2025-08-18T11:08:04.1466667' AS DateTime2), 2, N'10052-002')
INSERT [catalogue].[AdditionalServices] ([CatalogueItemId], [Summary], [FullDescription], [LastUpdated], [LastUpdatedBy], [SolutionId]) VALUES (N'99999-89-A01', N'Addition to NotEmis Web GP', N'NotEmis Web GP Addition Full Description', CAST(N'2025-08-18T11:08:03.5700000' AS DateTime2), 2, N'99999-89')

